mapper.select:
SELECT
    mr.*,
    ss.name AS supplier_name,
    su.phone,
    su.username AS number,
    mr.behavior_total_score,
    IFNULL(t1.deducted_behavior_score, 0) AS deducted_behavior_score,
    mr.behavior_total_score - IFNULL(t1.deducted_behavior_score, 0) AS remaining_behavior_score,
    IFNULL(t1.penalty, 0) as cumulative_penalty
FROM mes_roster mr
LEFT JOIN scm_supplier ss ON ss.bool_delete_enum = 0 AND ss.id = mr.supplier_id
LEFT JOIN sys_user su ON su.bool_delete_enum = 0 AND su.id = mr.user_id
LEFT JOIN (
    SELECT
        mbq.duty_id,
        SUM(mbq.behavior_score) AS deducted_behavior_score,
        SUM(mbq.penalty) AS penalty
    FROM mes_building_qhse mbq
    WHERE mbq.bool_delete_enum = 0
    
        AND YEAR(mbq.create_time) = #{year}
    
    
        AND mbq.duty_id = #{userId}
    
    GROUP BY mbq.duty_id
) t1 ON t1.duty_id = mr.user_id
WHERE mr.bool_delete_enum = 0

    AND mr.supplier_id = #{supplierId}


    AND mr.employee_category = #{employeeCategory}


    
    AND mr.name LIKE #{nameLike}


    
    AND mr.id_number LIKE #{idNumberLike}


    
    AND su.phone LIKE #{phoneLike}


    AND mr.user_id = #{userId}

select mbq.create_time AS record_date, mbq.qhse_number, su.name recorder_name, mbq.behavior_score, mbq.penalty FROM mes_building_qhse mbq LEFT JOIN sys_user su ON su.bool_delete_enum = 0 AND su.id = mbq.user_id WHERE mbq.bool_delete_enum = 0
AND mbq.duty_id = #{userId}
AND YEAR(mbq.create_time) = #{year}
